from pathlib import Path
from datetime import datetime,timezone,timedelta
from urllib.parse import urljoin,urlsplit
from concurrent.futures import ThreadPoolExecutor,as_completed
import requests,json,hashlib,re
from bs4 import BeautifulSoup
root=Path.cwd();out=root/'reports/research/510300_bankers_loan_demand_source_qualification_v1';sources=out/'sources'
proto=json.loads((out/'protocol.json').read_text(encoding='utf-8-sig'))
now=lambda:datetime.now(timezone(timedelta(hours=8))).isoformat()
def save(n,o):
 p=out/n
 if p.exists():raise RuntimeError('不覆盖来源原件：'+n)
 p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def official(u):
 host=urlsplit(u).hostname or ''
 return host=='pbc.gov.cn' or host.endswith('.pbc.gov.cn')
def get_one(url,name,role,quarter=None):
 rec={'url':url,'role':role,'quarter':quarter,'requested_at':now(),'attempts':1,'direct_local_receipt':True}
 cached=sources/name
 if cached.exists():
  if not name.startswith('catalog_page_'):raise RuntimeError('不得重新取得/覆盖既有目标原件：'+name)
  b=cached.read_bytes()
  return {'url':url,'role':role,'quarter':quarter,'path':cached.relative_to(root).as_posix(),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'success':True,'local_cached_first_acquisition_resumed':True,'no_new_request':True,'final_url':url,'final_url_basis':'用原实际分页请求地址解析根相对链接；首次最终URL未持久化，不能冒称已保存重定向记录','requested_at':'NOT_DURABLY_SAVED_IN_INTERRUPTED_CATALOG_RECEIPT','attempts':1,'saved_object_mtime':datetime.fromtimestamp(cached.stat().st_mtime,timezone(timedelta(hours=8))).isoformat()}
 try:
  if not official(url):raise RuntimeError('非原官方域')
  s=requests.Session();s.trust_env=False
  r=s.get(url,timeout=(10,25),headers={'User-Agent':'Mozilla/5.0'},allow_redirects=True)
  b=r.content
  rec.update(status_code=r.status_code,final_url=r.url,content_type=r.headers.get('Content-Type'),bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
  if not official(r.url):raise RuntimeError('重定向离开原官方域')
  if r.status_code!=200 or len(b)>20*1024*1024:raise RuntimeError('原请求状态/大小不合格')
  p=sources/name
  if p.exists():raise RuntimeError('目标原件已有，不覆盖')
  p.write_bytes(b);rec.update(path=p.relative_to(root).as_posix(),success=True)
 except Exception as exc:rec.update(success=False,error=type(exc).__name__+': '+str(exc))
 rec['completed_at']=now()
 return rec
quarters=[q.replace('-','') for q in proto['target_quarters']]
found={q:[] for q in quarters}
catalog=[]
rootreceipt=json.loads((out/'目录根页首次本地原件回执.json').read_text(encoding='utf-8-sig'))
catalog.append(rootreceipt)
current=rootreceipt
visited={current['url']}
chmap={'一':'1','二':'2','三':'3','四':'4'}
for pn in range(1,19):
 if not current.get('success'):break
 b=(root/current['path']).read_bytes();soup=BeautifulSoup(b,'html.parser')
 for a in soup.find_all('a',href=True):
  title=re.sub(r'\s+','',a.get_text(' ',strip=True))
  m=re.fullmatch(r'([12]\d{3})年(?:第)?([一二三四1-4])季度银行家问卷调查报告',title)
  if not m:continue
  q=m.group(1)+'Q'+chmap.get(m.group(2),m.group(2))
  if q not in found:continue
  u=urljoin(current['final_url'],a['href'])
  if not official(u):continue
  if not any(x['url']==u for x in found[q]):
   found[q].append({'quarter':q,'title':title,'url':u,'catalog_path':current['path'],'catalog_sha256':current['sha256']})
 print('原目录页',pn,'已定位季度',sum(bool(v) for v in found.values()),flush=True)
 if all(found.values()):break
 link=None
 for a in soup.find_all('a'):
  if a.get_text(' ',strip=True)=='下一页':
   link=a.get('tagname')
   if not link:
    m=re.search(r"queryArticleByCondition\(this,'([^']+)'\)",a.get('onclick',''))
    if m:link=m.group(1)
   break
 if not link:break
 u=urljoin(current['final_url'],link)
 if u in visited:break
 visited.add(u)
 current=get_one(u,f'catalog_page_{pn+1:02d}.html','actual_same_catalog_next_link')
 catalog.append(current)
save('同一官方目录全部实际分页回执.json',{'completed_at':now(),'receipts':catalog,'actual_pages_received':sum(x.get('success',False) for x in catalog),'registered_max_pages':18,'followed_only_actual_original_next_links':True,'quarter_candidates':found,'all_29_current_quarter_pages_located':all(len(v)==1 for v in found.values())})
release_jobs=[(q,v[0]) for q,v in found.items() if len(v)==1]
releases=[]
with ThreadPoolExecutor(max_workers=2) as pool:
 futures={pool.submit(get_one,j['url'],f'release_{q}.html','original_current_quarter_release',q):q for q,j in release_jobs}
 for f in as_completed(futures):
  r=f.result();releases.append(r);print('原发布页',r['quarter'],'收到',r['success'],flush=True)
releases.sort(key=lambda r:r['quarter'])
save('全目标发布页原件回执.json',{'completed_at':now(),'receipts':releases,'target_quarters_preserved':quarters})
pdfjobs=[]
releasematrix=[]
for r in releases:
 item={'quarter':r['quarter'],'release_receipt':r,'original_publication_display':'UNKNOWN','pdf_candidates':[]}
 if r.get('success'):
  b=(root/r['path']).read_bytes();soup=BeautifulSoup(b,'html.parser')
  body=soup.get_text(' ',strip=True)
  title=next(x for x in found[r['quarter']] if x['url']==r['url'])['title']
  ds=re.findall(r'(?<!\d)(20\d{2}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})(?!\d)',body)
  ds=list(dict.fromkeys(ds))
  if len(ds)==1:item['original_publication_display']=ds[0]
  item['all_visible_clock_candidates']=ds
  item['release_title_present']=title in re.sub(r'\s+','',body)
  item['target_named_numeric_in_release_body']=re.findall(r'贷款总体需求指数为\s*([0-9]+(?:\.[0-9]+)?)\s*[%％]',body)
  node=soup.select_one('#zoom') or soup.select_one('.TRS_Editor') or soup.select_one('.TRS_PreAppend') or soup
  for a in node.find_all('a',href=True):
   u=urljoin(r['final_url'],a['href'])
   if urlsplit(u).path.lower().endswith('.pdf') and official(u):
    if not any(x['url']==u for x in item['pdf_candidates']):item['pdf_candidates'].append({'url':u,'link_text':a.get_text(' ',strip=True)})
  if len(item['pdf_candidates'])==1:
   pdfjobs.append((r['quarter'],item['pdf_candidates'][0]['url']))
 releasematrix.append(item)
save('全部原发布钟与实际附件链接.json',{'completed_at':now(),'quarters':releasematrix,'unique_original_attachment_jobs':pdfjobs})
pdfs=[]
with ThreadPoolExecutor(max_workers=2) as pool:
 futures={pool.submit(get_one,url,f'{q}.pdf','original_current_quarter_pdf',q):q for q,url in pdfjobs}
 for f in as_completed(futures):
  r=f.result();pdfs.append(r);print('原报告PDF',r['quarter'],'收到',r['success'],flush=True)
pdfs.sort(key=lambda r:r['quarter'])
save('全部原报告PDF首次本地取得回执.json',{'completed_at':now(),'receipts':pdfs,'total_bytes':sum(x.get('bytes',0) for x in pdfs),'attachment_request_budget':29})
save('实际取件调用账本.json',{'completed_at':now(),'official_queries':4,'browser_target_open_reads_separate':3,'browser_catalog_lookup_reads_separate':1,
 'first_local_catalog_GETs':len(catalog),'first_local_release_GETs':len(releases),'first_local_attachment_GETs':len(pdfs),'URL_retry_count':0,
 'all_target_members_preserved':29,'new_equity_labels':0,'new_fits':0,'new_accounts':0,'source_code_edits':0,'authenticated_requests':0})
print('完整原目录/发布页/附件取件结束；季度',sum(len(v)==1 for v in found.values()),'原页',len(releases),'PDF',len(pdfs),'金融运行0',flush=True)
